"""Produce a review-only mode-2 native host contract. Does not build or execute."""
import argparse,hashlib,json,struct
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
FIX=ROOT/"target/animation/cid-child-mode2-fixtures-v1"
AUDIT=ROOT/"target/animation/cid-child-mode2-source-audit-v1.json"
INIT=ROOT/"target/animation/cid-node-init-actual-body-inputs-v1"
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def word(b,o):return struct.unpack_from("<I",b,o)[0]
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument("--out",type=Path,required=True);a=p.parse_args();a.out.resolve().relative_to((ROOT/"target").resolve())
 fm=json.loads((FIX/"manifest.json").read_text());assert sha(FIX/"fixtures.json")==fm["fixtures_sha256"];f=json.loads((FIX/"fixtures.json").read_text());idx=json.loads((INIT/"index.json").read_text());im=json.loads((INIT/"manifest.json").read_text());assert sha(INIT/"input.bin")==im["input_sha256"]
 source=json.loads(AUDIT.read_text());assert not source["native_executed"] and len(f["fixtures"])==64 and f["synthetic_stage_state"]
 raw=(INIT/"input.bin").read_bytes();seen=set()
 for case in f["fixtures"]:
  row=idx[case["body"]];assert row["body"] not in seen;seen.add(row["body"]);assert row["key"]==case["key"] and row["source_sha256"]==case["source_sha256"]
  packet=raw[row["input_offset"]:row["input_offset"]+row["input_bytes"]];assert hashlib.sha256(packet[32:]).hexdigest()==row["block_projection_sha256"]
  parent,child,count=case["parent_ordinal"],case["first_child_ordinal"],case["source_child_count"];assert 0<=parent<row["count"] and 0<count and child+count<=row["count"]
  b=packet[32+parent*1128:32+(parent+1)*1128];c=packet[32+child*1128:32+(child+1)*1128];assert word(b,0x204)==child and word(b,0x208)==count and word(c,0x1fc)==parent
  for block,offset,key in [(b,0x344,"parent_definition_344_bits"),(c,0x128,"child_definition_128_bits"),(c,0x350,"child_definition_350_bits")]:assert [word(block,offset+i*4)for i in range(len(case[key]))]==case[key]
  s=case["synthetic_stage"];assert s["mode_238"]==2 and s["flags_1ac_bytes"][0]&7!=4 and s["other_child_flags_low3"]==4 and s["cid_scale_bits"]==0x3f800000 and s["initial_counters"]==[0,0,0] and not any(s["initial_position_bits"]+s["initial_quaternion_bits"])
 out=dict(schema="cid-child-mode2-native-host-contract-v1",status="DESIGN ONLY: no host implementation, binary, execution or acceptance",fixture_count=64,fixture_kind="source body geometry with synthetic stage state",source_spans=source["source_spans"],constants=source["absolute_constants"],calls=source["all_calls"],carrier_design={"base":"00670000","code_pages":["00990000","009E0000"],"data_pages":["013E0000","01470000"],"poison_other_code":"CC", "forbidden_unmapped_call":"009E6890", "header_first_page_reservation":"00670000-00670FFF", "owned_base":"29000000", "no_WX":True},arguments=["CID pointer; CID+70 = 1.0", "parent node pointer; +0 Definition, +0C child-array pointer", "counter mode2 pointer", "counter active-mode1-or2 pointer", "counter unskipped pointer", "position accumulator pointer (3 zero floats)", "quaternion accumulator pointer (4 zero floats)", "aggregate flags pointer initialized 04 00 FF FF"],native_preconditions=["Source parent and child Definition offsets materialized from pinned input; first child +0 references child Definition", "child count from parent Definition+208, maximum bounded by fixture array", "child 0 stage pose from synthetic fixture, flags low3 != 4, mode exactly 2", "every remaining child low3 == 4 and all other bytes poison", "x87 control 027F, MXCSR 1F80, DF clear; exact stack alignment and callee-saved registers independently checked", "read original code/data exact against pinned actual Spore source before invocation"],allowed_writes=["active child +1AC..1AF = 04 00 FF FF", "active child +210..213 = 00 00 80 BF", "three counters and 3-float position / 4-float quaternion accumulators", "x87/SSE status and bounded scratch stack"],mandatory_guards=["canaries before and after every host buffer, including contiguous child node array, definition, CID, all accumulators and aggregate flags", "whole-buffer comparison for definition, CID, fixture input, aggregate flags and untouched child/parent bytes", "per-byte node write mask for only +1AC..1AF and +210..213 on active child", "guard and read back all unselected child bytes; reject mode 0/1 or any non-skipped sibling", "host-owned stack checkpoint, stack canaries, bounded 9E7C80 and 99BE70 call depth", "reject every extra source call and all writable-executable mappings; verify sparse PE permissions/import closure and actual linked bytes", "two poison patterns plus protocol malformed cases; independent exact binary and runner reviews before any invocation"],limitations="No native host generated. No source execution, numeric expected output, Rust acceptance, full 009E8930/009F4730, real animation, actor association, or complete CID claim.",pins={str(q):sha(q)for q in [Path(__file__),FIX/"fixtures.json",FIX/"manifest.json",INIT/"input.bin",INIT/"index.json",INIT/"manifest.json",AUDIT]})
 with a.out.open("x") as h:json.dump(out,h,indent=2);h.write("\n")
 print(sha(a.out))
if __name__=="__main__":main()
